import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Cz0TtJv6.js";const u=JSON.parse('{"title":"Easy setup (Railway)","description":"One-click Railway deploy for DLMM Bot. Paper first, then live from the dashboard.","frontmatter":{"title":"Easy setup (Railway)","description":"One-click Railway deploy for DLMM Bot. Paper first, then live from the dashboard."},"headers":[],"relativePath":"easy.md","filePath":"easy.md","lastUpdated":1786725701000}'),s={name:"easy.md"};function i(l,e,n,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="easy-setup-railway" tabindex="-1">Easy setup (Railway) <a class="header-anchor" href="#easy-setup-railway" aria-label="Permalink to &quot;Easy setup (Railway)&quot;">​</a></h1><p>One service. Attach a volume, open the URL, finish secrets in the dashboard.</p><p class="cta-row"><a class="doc-btn" href="https://railway.com?referralCode=SCj9lN" target="_blank" rel="noreferrer">Deploy on Railway</a><a class="doc-btn ghost" href="./api-keys">API keys</a><a class="doc-btn ghost" href="./agents">For AI agents</a></p><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><h3 id="_1-fork-then-deploy-from-github" tabindex="-1">1. Fork, then deploy from GitHub <a class="header-anchor" href="#_1-fork-then-deploy-from-github" aria-label="Permalink to &quot;1. Fork, then deploy from GitHub&quot;">​</a></h3><p>Railway only deploys GitHub repos <strong>you can access</strong>. You are not a collaborator on ours, so:</p><ol><li>On GitHub: open <a href="https://github.com/CryptoGnome/dlmmbot" target="_blank" rel="noreferrer">CryptoGnome/dlmmbot</a> → <strong>Fork</strong> (your account / org).</li><li>Railway → <strong>New Project → Deploy from GitHub</strong> → pick <strong>your fork</strong> (<code>you/dlmmbot</code>). One service is enough — start/build come from <code>railway.toml</code>.</li></ol><p>Connect the Railway GitHub App to that fork if prompted. Later updates: merge/rebase upstream <code>main</code> into your fork (or sync fork in GitHub), and Railway will redeploy.</p><p>Boot defaults: paper mode, public <code>PORT</code>, volume-backed <code>config.toml</code> / <code>.env</code>.</p><p>Set a strong dash token <strong>before</strong> you open the site (do not use a short password):</p><ol><li>Generate one: <code>node -e &quot;console.log(require(&#39;crypto&#39;).randomBytes(24).toString(&#39;hex&#39;))&quot;</code></li><li>Railway → Variables → <code>DASH_TOKEN</code> = that value → Redeploy</li></ol><p>If you skip this, the bot still generates a token onto the volume (logs only show the first 8 characters on purpose — deploy logs get screenshotted). You would then need shell access to <code>/app/data/.env</code> to read it. Setting the Railway variable is the safe path.</p><h3 id="_2-volume-at-app-data" tabindex="-1">2. Volume at <code>/app/data</code> <a class="header-anchor" href="#_2-volume-at-app-data" aria-label="Permalink to &quot;2. Volume at `/app/data`&quot;">​</a></h3><p>Service → <strong>Volumes</strong> → Add → mount <code>/app/data</code>. Keeps SQLite, Settings, and the wallet across redeploys. Redeploy once after attaching.</p><h3 id="_3-public-domain" tabindex="-1">3. Public domain <a class="header-anchor" href="#_3-public-domain" aria-label="Permalink to &quot;3. Public domain&quot;">​</a></h3><p><strong>Settings → Networking → Generate domain.</strong> That’s the dashboard URL.</p><h2 id="open-the-dashboard" tabindex="-1">Open the dashboard <a class="header-anchor" href="#open-the-dashboard" aria-label="Permalink to &quot;Open the dashboard&quot;">​</a></h2><p>Open the domain. Log in with the <code>DASH_TOKEN</code> you set as a Railway variable (<code>?token=…</code> or the login box).</p><h2 id="finish-in-settings" tabindex="-1">Finish in Settings <a class="header-anchor" href="#finish-in-settings" aria-label="Permalink to &quot;Finish in Settings&quot;">​</a></h2><p>First login opens a wizard: <strong>accept the Terms &amp; risk waiver</strong>, then only the steps still missing (RPC, Jupiter, <strong>burner wallet</strong>, paper/live). If you already set <code>RPC_URL</code> / <code>JUPITER_API_KEY</code> / <code>GMGN_API_KEY</code> as Railway variables (and redeployed), the wizard detects them and skips those prompts — paste only to replace. Writes go to <code>/app/data</code> — the git checkout stays clean.</p><p>After Finish, the trading engine stays <strong>OFF</strong> (header toggle). Flip it ON when you want paper (or live) ticks. Choosing <strong>live</strong> in the wizard (or Settings) restarts the farmer once so the header shows LIVE.</p><table tabindex="0"><thead><tr><th>Key</th><th>Required</th><th>Get it</th></tr></thead><tbody><tr><td><code>RPC_URL</code></td><td>Yes</td><td><a href="https://dashboard.helius.dev/signup" target="_blank" rel="noreferrer">Helius</a> mainnet URL</td></tr><tr><td><code>JUPITER_API_KEY</code></td><td>Before live</td><td><a href="https://developers.jup.ag/portal" target="_blank" rel="noreferrer">Jupiter Portal</a></td></tr><tr><td><code>GMGN_API_KEY</code></td><td>Optional</td><td><a href="https://gmgn.ai/ai" target="_blank" rel="noreferrer">gmgn.ai/ai</a></td></tr></tbody></table><p>On the wallet step (or later under <strong>Settings → Wallet &amp; secrets</strong>):</p><ol><li><strong>Create new</strong> (recommended) — dashboard generates a fresh Solana keypair, you set a passphrase, retype it, and save the one-time backup somewhere safe offline.</li><li>Or <strong>Import Phantom</strong> — paste a <strong>burner</strong> base58 private key only (never your main wallet). Same passphrase encryption.</li></ol><p>Either way the key is stored encrypted as <code>wallet.enc.json</code> on the volume. Stay in <strong>paper</strong> until you’re comfortable. Optional: set <code>WALLET_PASSPHRASE</code> on Railway to auto-unlock on boot.</p><p class="cta-row"><a class="doc-btn ghost" href="./api-keys">Full key signup</a><a class="doc-btn ghost" href="./dashboard">Dashboard / wallet</a><a class="doc-btn ghost" href="./profiles">Settings profiles</a></p><h2 id="going-live" tabindex="-1">Going live <a class="header-anchor" href="#going-live" aria-label="Permalink to &quot;Going live&quot;">​</a></h2><p>Paper first. When you’re ready for real SOL:</p><h3 id="_1-burner-wallet" tabindex="-1">1. Burner wallet <a class="header-anchor" href="#_1-burner-wallet" aria-label="Permalink to &quot;1. Burner wallet&quot;">​</a></h3><p>If you skipped the wallet in the wizard: <strong>Settings → Wallet &amp; secrets → Create</strong> (or Import a dedicated burner). Confirm the public address shown in the dash (header chip / Settings).</p><h3 id="_2-fund-it" tabindex="-1">2. Fund it <a class="header-anchor" href="#_2-fund-it" aria-label="Permalink to &quot;2. Fund it&quot;">​</a></h3><p>Send <strong>SOL</strong> to that public address from another wallet (Phantom, exchange withdraw, etc.). Start small.</p><p>You need enough for:</p><ul><li>Position size(s) you expect to open</li><li>An operational reserve (~1 SOL + ~10% of bankroll is held back for rent / priority / claims — see <a href="./risk">Risk &amp; sizing</a>)</li><li>A little headroom for failed tx retries</li></ul><p>Paper mode does not need funded SOL. Live will not trade usefully on an empty wallet.</p><h3 id="_3-unlock" tabindex="-1">3. Unlock <a class="header-anchor" href="#_3-unlock" aria-label="Permalink to &quot;3. Unlock&quot;">​</a></h3><p>Unlock the encrypted wallet in Settings (or rely on <code>WALLET_PASSPHRASE</code> on Railway). The farmer can only sign when the key is unlocked into runtime env.</p><h3 id="_4-flip-both-live-switches" tabindex="-1">4. Flip both live switches <a class="header-anchor" href="#_4-flip-both-live-switches" aria-label="Permalink to &quot;4. Flip both live switches&quot;">​</a></h3><p>Needs <strong>both</strong>:</p><ul><li><code>FARMER_MODE=live</code> (Railway variable or Settings → secrets)</li><li><code>[exec] mode = &quot;live&quot;</code> in Settings / <code>data/config.toml</code></li></ul><p>One switch alone stays paper. Restart / redeploy after both are set. <strong>One farmer process per wallet.</strong></p><p class="note bad">Burner only. You can lose 100%. Accept the <a href="./terms">Terms</a> — we are not liable for losses.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>Hobby (~$5) plus usage after trial credits — a volume needs a paid tier. Own hardware: <a href="./advanced">Advanced</a>.</p><p class="cta-row"><a class="doc-btn ghost" href="https://railway.com/pricing?referralCode=SCj9lN" target="_blank" rel="noreferrer">Railway pricing</a><a class="doc-btn ghost" href="./advanced">Advanced setup</a></p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Native module build fail</td><td>Node 20; check <code>better-sqlite3</code> logs</td></tr><tr><td>Dash unauthorized</td><td>Confirm Railway <code>DASH_TOKEN</code> matches what you paste / <code>?token=</code></td></tr><tr><td>History / Settings wiped</td><td>Volume at <code>/app/data</code>, then redeploy</td></tr><tr><td>Healthcheck failing</td><td>Wait for first build; path is <code>/health</code></td></tr></tbody></table>',47)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
